const fs=require('fs'),path=require('path'),{execSync}=require('child_process');
const files={"frontend/src/app/dashboard/products/[productId]/page.tsx":"\"use client\";\nimport { useState, useRef, useCallback } from \"react\";\nimport { useParams, useRouter } from \"next/navigation\";\nimport { useQuery, useMutation, useQueryClient } from \"@tanstack/react-query\";\nimport { motion } from \"framer-motion\";\nimport { useTheme } from \"../../../../components/layout/DashboardLayout\";\nimport { useAuthStore } from \"../../../../store/auth.store\";\nimport { api, uploadAPI } from \"../../../../lib/api\";\nimport toast from \"react-hot-toast\";\nimport Link from \"next/link\";\nimport {\n  ArrowLeft, Save, Trash2, Upload, X, Plus, Eye,\n  Package, Tag, BarChart2, Globe, RefreshCw, ExternalLink, Image as ImageIcon,\n} from \"lucide-react\";\n\nconst V = { v500:\"#6B35E8\", v400:\"#8B5CF6\", green:\"#10B981\", amber:\"#F59E0B\", red:\"#EF4444\" };\n\nexport default function ProductEditPage() {\n  const { productId } = useParams<{ productId: string }>();\n  const router = useRouter();\n  const qc = useQueryClient();\n  const { theme } = useTheme();\n  const isDark = theme === \"dark\";\n  const storeId = useAuthStore(s => s.user?.stores?.[0]?.id);\n\n  const C = {\n    card:   isDark ? \"rgba(255,255,255,0.04)\" : \"#fff\",\n    text:   isDark ? \"#F0ECFF\" : \"#130D2E\",\n    muted:  isDark ? \"rgba(240,236,255,0.45)\" : \"rgba(19,13,46,0.5)\",\n    border: isDark ? \"rgba(107,53,232,0.15)\" : \"rgba(107,53,232,0.12)\",\n    faint:  isDark ? \"rgba(107,53,232,0.06)\" : \"rgba(107,53,232,0.04)\",\n    input:  isDark ? \"rgba(255,255,255,0.06)\" : \"#fff\",\n    bg:     isDark ? \"#08051A\" : \"#F4F2FB\",\n  };\n\n  const inp: any = { width:\"100%\", padding:\"11px 14px\", borderRadius:11, border:`1px solid ${C.border}`, background:C.input, color:C.text, fontSize:13, fontFamily:\"inherit\", outline:\"none\" };\n\n  const { data: productData, isLoading } = useQuery({\n    queryKey: [\"product\", productId],\n    queryFn: () => api.get(`/products/${storeId}/${productId}`).then(r => r.data.data),\n    enabled: !!storeId && !!productId,\n  });\n\n  const [form, setForm] = useState<any>(null);\n  const [images, setImages] = useState<string[]>([]);\n  const [uploading, setUploading] = useState(false);\n  const [activeTab, setActiveTab] = useState<\"details\"|\"images\"|\"seo\"|\"variants\">(\"details\");\n  const fileRef = useRef<HTMLInputElement>(null);\n\n  // Sync form when product loads\n  if (productData && !form) {\n    setForm({\n      name: productData.name || \"\",\n      price: productData.price || \"\",\n      compareAtPrice: productData.compareAtPrice || \"\",\n      costPrice: productData.costPrice || \"\",\n      description: productData.description || \"\",\n      category: productData.category || \"\",\n      tags: (productData.tags || []).join(\", \"),\n      sku: productData.sku || \"\",\n      barcode: productData.barcode || \"\",\n      weight: productData.weight || \"\",\n      inventory: productData.inventory ?? \"\",\n      trackInventory: productData.trackInventory ?? true,\n      status: productData.status || \"ACTIVE\",\n      metaTitle: productData.metaTitle || \"\",\n      metaDescription: productData.metaDescription || \"\",\n    });\n    setImages(productData.images || []);\n  }\n\n  const saveMut = useMutation({\n    mutationFn: () => api.put(`/products/${storeId}/${productId}`, {\n      ...form,\n      price: Number(form.price),\n      compareAtPrice: form.compareAtPrice ? Number(form.compareAtPrice) : undefined,\n      costPrice: form.costPrice ? Number(form.costPrice) : undefined,\n      weight: form.weight ? Number(form.weight) : undefined,\n      inventory: form.inventory !== \"\" ? Number(form.inventory) : undefined,\n      tags: form.tags ? form.tags.split(\",\").map((t: string) => t.trim()).filter(Boolean) : [],\n      images,\n    }),\n    onSuccess: () => { toast.success(\"Product saved\"); qc.invalidateQueries({ queryKey:[\"product\", productId] }); },\n    onError: (e: any) => toast.error(e.response?.data?.message || \"Save failed\"),\n  });\n\n  const deleteMut = useMutation({\n    mutationFn: () => api.delete(`/products/${storeId}/${productId}`),\n    onSuccess: () => { toast.success(\"Product deleted\"); router.push(\"/dashboard/products\"); },\n    onError: () => toast.error(\"Delete failed\"),\n  });\n\n  const handleUpload = useCallback(async (files: FileList | null) => {\n    if (!files?.length) return;\n    setUploading(true);\n    for (const file of Array.from(files)) {\n      try {\n        const fd = new FormData(); fd.append(\"image\", file);\n        const r = await uploadAPI.post(\"/upload/image\", fd);\n        setImages(prev => [...prev, r.data.url]);\n      } catch { toast.error(`Failed to upload ${file.name}`); }\n    }\n    setUploading(false);\n  }, []);\n\n  if (isLoading || !form) return (\n    <div style={{ display:\"flex\", alignItems:\"center\", justifyContent:\"center\", height:400 }}>\n      <RefreshCw size={24} color={V.v400} style={{ animation:\"spin 0.7s linear infinite\" }}/>\n      <style>{\"@keyframes spin{to{transform:rotate(360deg)}}\"}</style>\n    </div>\n  );\n\n  const TABS = [\n    { id:\"details\",  label:\"Details\",  icon:Package },\n    { id:\"images\",   label:\"Images\",   icon:ImageIcon },\n    { id:\"seo\",      label:\"SEO\",      icon:Globe },\n    { id:\"variants\", label:\"Variants\", icon:Tag },\n  ];\n\n  const margin = form.price && form.costPrice\n    ? Math.round(((Number(form.price) - Number(form.costPrice)) / Number(form.price)) * 100)\n    : null;\n\n  return (\n    <div style={{ maxWidth:900, margin:\"0 auto\", fontFamily:\"'Plus Jakarta Sans',system-ui,sans-serif\" }}>\n      {/* Header */}\n      <div style={{ display:\"flex\", alignItems:\"center\", justifyContent:\"space-between\", marginBottom:24, flexWrap:\"wrap\", gap:12 }}>\n        <div style={{ display:\"flex\", alignItems:\"center\", gap:12 }}>\n          <Link href=\"/dashboard/products\" style={{ width:36, height:36, borderRadius:10, background:C.card, border:`1px solid ${C.border}`, display:\"flex\", alignItems:\"center\", justifyContent:\"center\", textDecoration:\"none\", color:C.muted }}>\n            <ArrowLeft size={16}/>\n          </Link>\n          <div>\n            <h1 style={{ fontSize:18, fontWeight:900, color:C.text, margin:0, letterSpacing:\"-0.03em\" }}>\n              {form.name || \"Product\"}\n            </h1>\n            <p style={{ fontSize:12, color:C.muted, margin:0 }}>\n              {productData?.status === \"ACTIVE\" ? \"✅ Live\" : \"⏸ Draft\"} · ID: {productId?.slice(-8)}\n            </p>\n          </div>\n        </div>\n        <div style={{ display:\"flex\", gap:8 }}>\n          <a href={`/store/${useAuthStore.getState().user?.stores?.[0]?.slug}/product/${productId}`}\n            target=\"_blank\" rel=\"noreferrer\"\n            style={{ display:\"flex\", alignItems:\"center\", gap:6, padding:\"9px 14px\", borderRadius:10, border:`1px solid ${C.border}`, background:C.card, color:C.muted, textDecoration:\"none\", fontSize:13, fontWeight:600 }}>\n            <Eye size={13}/> Preview\n          </a>\n          <button onClick={() => { if(confirm(\"Delete this product?\")) deleteMut.mutate(); }}\n            style={{ padding:\"9px 14px\", borderRadius:10, border:\"1px solid rgba(239,68,68,0.2)\", background:\"rgba(239,68,68,0.06)\", color:V.red, cursor:\"pointer\", fontSize:13, fontWeight:600, fontFamily:\"inherit\", display:\"flex\", alignItems:\"center\", gap:6 }}>\n            <Trash2 size={13}/>\n          </button>\n          <button onClick={() => saveMut.mutate()} disabled={saveMut.isPending}\n            style={{ display:\"flex\", alignItems:\"center\", gap:6, padding:\"9px 18px\", borderRadius:10, border:\"none\", cursor:\"pointer\", background:\"linear-gradient(135deg,#2D1B69,#6B35E8)\", color:\"#fff\", fontSize:13, fontWeight:700, fontFamily:\"inherit\", boxShadow:\"0 4px 16px rgba(107,53,232,0.25)\" }}>\n            {saveMut.isPending ? <RefreshCw size={13} style={{ animation:\"spin 0.7s linear infinite\" }}/> : <Save size={13}/>}\n            {saveMut.isPending ? \"Saving…\" : \"Save\"}\n          </button>\n        </div>\n      </div>\n\n      {/* Stats strip */}\n      <div style={{ display:\"grid\", gridTemplateColumns:\"repeat(4,1fr)\", gap:10, marginBottom:20 }} className=\"stats-row\">\n        {[\n          { label:\"Price\",       value:form.price ? `₦${Number(form.price).toLocaleString()}` : \"—\" },\n          { label:\"Cost\",        value:form.costPrice ? `₦${Number(form.costPrice).toLocaleString()}` : \"—\" },\n          { label:\"Margin\",      value:margin !== null ? `${margin}%` : \"—\", color:margin && margin > 40 ? V.green : V.amber },\n          { label:\"Stock\",       value:form.trackInventory ? (form.inventory || \"0\") : \"∞\" },\n        ].map(s => (\n          <div key={s.label} style={{ padding:\"12px 16px\", borderRadius:12, background:C.card, border:`1px solid ${C.border}` }}>\n            <p style={{ fontSize:11, color:C.muted, margin:\"0 0 4px\" }}>{s.label}</p>\n            <p style={{ fontSize:16, fontWeight:800, color:s.color||C.text, margin:0, letterSpacing:\"-0.03em\" }}>{s.value}</p>\n          </div>\n        ))}\n      </div>\n\n      {/* Tabs */}\n      <div style={{ display:\"flex\", gap:2, marginBottom:20, background:C.faint, borderRadius:14, padding:4, border:`1px solid ${C.border}`, width:\"fit-content\" }}>\n        {TABS.map(tab => {\n          const Icon = tab.icon;\n          return (\n            <button key={tab.id} onClick={() => setActiveTab(tab.id as any)}\n              style={{ display:\"flex\", alignItems:\"center\", gap:7, padding:\"8px 16px\", borderRadius:11, border:\"none\", cursor:\"pointer\", fontSize:13, fontWeight:activeTab===tab.id?700:500, fontFamily:\"inherit\", background:activeTab===tab.id?C.card:\"transparent\", color:activeTab===tab.id?C.text:C.muted, boxShadow:activeTab===tab.id?\"0 1px 4px rgba(0,0,0,0.08)\":\"none\", transition:\"all 0.15s\" }}>\n              <Icon size={13}/> {tab.label}\n            </button>\n          );\n        })}\n      </div>\n\n      <div style={{ display:\"grid\", gridTemplateColumns:\"1fr 300px\", gap:16 }} className=\"edit-grid\">\n        {/* Main content */}\n        <div>\n          {activeTab === \"details\" && (\n            <motion.div initial={{ opacity:0, y:8 }} animate={{ opacity:1, y:0 }}\n              style={{ background:C.card, borderRadius:18, padding:24, border:`1px solid ${C.border}`, display:\"flex\", flexDirection:\"column\", gap:16 }}>\n              <div>\n                <label style={{ fontSize:12, fontWeight:700, color:C.muted, display:\"block\", marginBottom:6 }}>Product name *</label>\n                <input value={form.name} onChange={e => setForm((f:any) => ({...f, name:e.target.value}))} style={inp} placeholder=\"e.g. Blue Wireless Earbuds\"/>\n              </div>\n              <div>\n                <label style={{ fontSize:12, fontWeight:700, color:C.muted, display:\"block\", marginBottom:6 }}>Description</label>\n                <textarea value={form.description} onChange={e => setForm((f:any) => ({...f, description:e.target.value}))} rows={6}\n                  placeholder=\"Describe the product — what it is, what makes it great, who it's for…\"\n                  style={{ ...inp, resize:\"vertical\" }}/>\n              </div>\n              <div style={{ display:\"grid\", gridTemplateColumns:\"1fr 1fr 1fr\", gap:12 }}>\n                <div>\n                  <label style={{ fontSize:12, fontWeight:700, color:C.muted, display:\"block\", marginBottom:6 }}>Sell price (₦) *</label>\n                  <input type=\"number\" value={form.price} onChange={e => setForm((f:any) => ({...f, price:e.target.value}))} style={inp} placeholder=\"0\"/>\n                </div>\n                <div>\n                  <label style={{ fontSize:12, fontWeight:700, color:C.muted, display:\"block\", marginBottom:6 }}>Compare price (₦)</label>\n                  <input type=\"number\" value={form.compareAtPrice} onChange={e => setForm((f:any) => ({...f, compareAtPrice:e.target.value}))} style={inp} placeholder=\"0\"/>\n                </div>\n                <div>\n                  <label style={{ fontSize:12, fontWeight:700, color:C.muted, display:\"block\", marginBottom:6 }}>Cost price (₦)</label>\n                  <input type=\"number\" value={form.costPrice} onChange={e => setForm((f:any) => ({...f, costPrice:e.target.value}))} style={inp} placeholder=\"0\"/>\n                </div>\n              </div>\n              <div style={{ display:\"grid\", gridTemplateColumns:\"1fr 1fr\", gap:12 }}>\n                <div>\n                  <label style={{ fontSize:12, fontWeight:700, color:C.muted, display:\"block\", marginBottom:6 }}>SKU</label>\n                  <input value={form.sku} onChange={e => setForm((f:any) => ({...f, sku:e.target.value}))} style={inp} placeholder=\"SKU-001\"/>\n                </div>\n                <div>\n                  <label style={{ fontSize:12, fontWeight:700, color:C.muted, display:\"block\", marginBottom:6 }}>Barcode</label>\n                  <input value={form.barcode} onChange={e => setForm((f:any) => ({...f, barcode:e.target.value}))} style={inp} placeholder=\"123456789\"/>\n                </div>\n              </div>\n              <div style={{ display:\"grid\", gridTemplateColumns:\"1fr 1fr\", gap:12 }}>\n                <div>\n                  <label style={{ fontSize:12, fontWeight:700, color:C.muted, display:\"block\", marginBottom:6 }}>Category</label>\n                  <input value={form.category} onChange={e => setForm((f:any) => ({...f, category:e.target.value}))} style={inp} placeholder=\"e.g. Electronics\"/>\n                </div>\n                <div>\n                  <label style={{ fontSize:12, fontWeight:700, color:C.muted, display:\"block\", marginBottom:6 }}>Weight (kg)</label>\n                  <input type=\"number\" value={form.weight} onChange={e => setForm((f:any) => ({...f, weight:e.target.value}))} style={inp} placeholder=\"0.5\"/>\n                </div>\n              </div>\n              <div>\n                <label style={{ fontSize:12, fontWeight:700, color:C.muted, display:\"block\", marginBottom:6 }}>Tags (comma separated)</label>\n                <input value={form.tags} onChange={e => setForm((f:any) => ({...f, tags:e.target.value}))} style={inp} placeholder=\"earbuds, wireless, bluetooth\"/>\n              </div>\n            </motion.div>\n          )}\n\n          {activeTab === \"images\" && (\n            <motion.div initial={{ opacity:0, y:8 }} animate={{ opacity:1, y:0 }}\n              style={{ background:C.card, borderRadius:18, padding:24, border:`1px solid ${C.border}` }}>\n              <p style={{ fontSize:14, fontWeight:700, color:C.text, margin:\"0 0 16px\" }}>Product images</p>\n              {/* Upload area */}\n              <div onClick={() => fileRef.current?.click()}\n                style={{ padding:\"32px 24px\", borderRadius:14, border:`2px dashed ${uploading?\"#8B5CF6\":C.border}`, textAlign:\"center\", cursor:\"pointer\", marginBottom:16, background:uploading?`${V.v500}06`:C.faint, transition:\"all 0.15s\" }}>\n                {uploading\n                  ? <><RefreshCw size={24} color=\"#8B5CF6\" style={{ margin:\"0 auto 8px\", animation:\"spin 0.7s linear infinite\", display:\"block\" }}/><p style={{ color:\"#8B5CF6\", margin:0, fontWeight:600, fontSize:13 }}>Uploading…</p></>\n                  : <><Upload size={24} color={C.muted as string} style={{ margin:\"0 auto 8px\", display:\"block\" }}/><p style={{ color:C.text, margin:\"0 0 4px\", fontWeight:600, fontSize:13 }}>Click to upload or drag & drop</p><p style={{ color:C.muted, margin:0, fontSize:11 }}>JPG, PNG, WebP up to 10MB</p></>\n                }\n                <input ref={fileRef} type=\"file\" multiple accept=\"image/*\" style={{ display:\"none\" }}\n                  onChange={e => handleUpload(e.target.files)}/>\n              </div>\n              {/* Image grid */}\n              {images.length > 0 ? (\n                <div style={{ display:\"grid\", gridTemplateColumns:\"repeat(4,1fr)\", gap:10 }}>\n                  {images.map((img, i) => (\n                    <div key={i} style={{ position:\"relative\", aspectRatio:\"1\", borderRadius:12, overflow:\"hidden\", border:`1px solid ${C.border}` }}>\n                      <img src={img} alt=\"\" style={{ width:\"100%\", height:\"100%\", objectFit:\"cover\" }}/>\n                      {i === 0 && <span style={{ position:\"absolute\", top:6, left:6, fontSize:9, fontWeight:700, background:\"rgba(107,53,232,0.9)\", color:\"#fff\", padding:\"2px 6px\", borderRadius:99 }}>MAIN</span>}\n                      <button onClick={() => setImages(imgs => imgs.filter((_,j) => j!==i))}\n                        style={{ position:\"absolute\", top:6, right:6, width:22, height:22, borderRadius:6, background:\"rgba(0,0,0,0.6)\", border:\"none\", cursor:\"pointer\", display:\"flex\", alignItems:\"center\", justifyContent:\"center\", color:\"#fff\" }}>\n                        <X size={11}/>\n                      </button>\n                    </div>\n                  ))}\n                  <div onClick={() => fileRef.current?.click()}\n                    style={{ aspectRatio:\"1\", borderRadius:12, border:`2px dashed ${C.border}`, display:\"flex\", alignItems:\"center\", justifyContent:\"center\", cursor:\"pointer\", background:C.faint }}>\n                    <Plus size={20} color={C.muted as string}/>\n                  </div>\n                </div>\n              ) : (\n                <p style={{ fontSize:13, color:C.muted, textAlign:\"center\", margin:0 }}>No images yet. Upload one above.</p>\n              )}\n            </motion.div>\n          )}\n\n          {activeTab === \"seo\" && (\n            <motion.div initial={{ opacity:0, y:8 }} animate={{ opacity:1, y:0 }}\n              style={{ background:C.card, borderRadius:18, padding:24, border:`1px solid ${C.border}`, display:\"flex\", flexDirection:\"column\", gap:16 }}>\n              <div style={{ padding:14, borderRadius:12, background:C.faint, border:`1px solid ${C.border}` }}>\n                <p style={{ fontSize:11, fontWeight:700, color:C.muted, margin:\"0 0 8px\", textTransform:\"uppercase\", letterSpacing:\"0.08em\" }}>Google preview</p>\n                <p style={{ fontSize:16, color:\"#1a0dab\", margin:\"0 0 2px\", fontWeight:500 }}>{form.metaTitle || form.name || \"Product title\"}</p>\n                <p style={{ fontSize:13, color:\"#006621\", margin:\"0 0 4px\" }}>droposhq.com/store/…/product/{productId}</p>\n                <p style={{ fontSize:13, color:\"#545454\", margin:0, lineHeight:1.5 }}>{form.metaDescription || form.description?.slice(0,160) || \"Product description…\"}</p>\n              </div>\n              <div>\n                <label style={{ fontSize:12, fontWeight:700, color:C.muted, display:\"block\", marginBottom:6 }}>Meta title</label>\n                <input value={form.metaTitle} onChange={e => setForm((f:any) => ({...f, metaTitle:e.target.value}))} maxLength={60} style={inp} placeholder={form.name}/>\n                <p style={{ fontSize:11, color:C.muted, margin:\"4px 0 0\", textAlign:\"right\" }}>{(form.metaTitle||\"\").length}/60</p>\n              </div>\n              <div>\n                <label style={{ fontSize:12, fontWeight:700, color:C.muted, display:\"block\", marginBottom:6 }}>Meta description</label>\n                <textarea value={form.metaDescription} onChange={e => setForm((f:any) => ({...f, metaDescription:e.target.value}))} maxLength={160} rows={3}\n                  style={{ ...inp, resize:\"none\" }} placeholder=\"Brief description for search engines…\"/>\n                <p style={{ fontSize:11, color:C.muted, margin:\"4px 0 0\", textAlign:\"right\" }}>{(form.metaDescription||\"\").length}/160</p>\n              </div>\n            </motion.div>\n          )}\n\n          {activeTab === \"variants\" && (\n            <motion.div initial={{ opacity:0, y:8 }} animate={{ opacity:1, y:0 }}\n              style={{ background:C.card, borderRadius:18, padding:24, border:`1px solid ${C.border}`, textAlign:\"center\" }}>\n              <Tag size={32} color=\"#8B5CF6\" style={{ margin:\"0 auto 12px\", display:\"block\" }}/>\n              <p style={{ fontSize:15, fontWeight:700, color:C.text, margin:\"0 0 8px\" }}>Variants</p>\n              <p style={{ fontSize:13, color:C.muted, margin:\"0 0 20px\" }}>Manage sizes, colours, and options for this product</p>\n              <Link href={`/dashboard/products/${productId}/variants`}\n                style={{ display:\"inline-flex\", alignItems:\"center\", gap:8, padding:\"11px 22px\", borderRadius:12, background:\"linear-gradient(135deg,#2D1B69,#6B35E8)\", color:\"#fff\", textDecoration:\"none\", fontSize:14, fontWeight:700 }}>\n                Manage variants <ExternalLink size={13}/>\n              </Link>\n            </motion.div>\n          )}\n        </div>\n\n        {/* Sidebar */}\n        <div style={{ display:\"flex\", flexDirection:\"column\", gap:12 }}>\n          {/* Status */}\n          <div style={{ background:C.card, borderRadius:16, padding:18, border:`1px solid ${C.border}` }}>\n            <p style={{ fontSize:12, fontWeight:700, color:C.muted, margin:\"0 0 10px\" }}>Status</p>\n            <select value={form.status} onChange={e => setForm((f:any) => ({...f, status:e.target.value}))}\n              style={{ ...inp, width:\"100%\" }}>\n              <option value=\"ACTIVE\">✅ Active — visible in store</option>\n              <option value=\"DRAFT\">⏸ Draft — hidden from store</option>\n              <option value=\"ARCHIVED\">🗄 Archived</option>\n            </select>\n          </div>\n\n          {/* Inventory */}\n          <div style={{ background:C.card, borderRadius:16, padding:18, border:`1px solid ${C.border}` }}>\n            <p style={{ fontSize:12, fontWeight:700, color:C.muted, margin:\"0 0 12px\" }}>Inventory</p>\n            <div style={{ display:\"flex\", alignItems:\"center\", gap:10, marginBottom:12 }}>\n              <input type=\"checkbox\" id=\"track\" checked={form.trackInventory}\n                onChange={e => setForm((f:any) => ({...f, trackInventory:e.target.checked}))}\n                style={{ accentColor:\"#6B35E8\", width:15, height:15 }}/>\n              <label htmlFor=\"track\" style={{ fontSize:13, color:C.text, cursor:\"pointer\" }}>Track inventory</label>\n            </div>\n            {form.trackInventory && (\n              <div>\n                <label style={{ fontSize:12, fontWeight:700, color:C.muted, display:\"block\", marginBottom:5 }}>Stock quantity</label>\n                <input type=\"number\" value={form.inventory} onChange={e => setForm((f:any) => ({...f, inventory:e.target.value}))} style={inp} min=\"0\" placeholder=\"0\"/>\n              </div>\n            )}\n          </div>\n\n          {/* Margin calculator */}\n          {margin !== null && (\n            <div style={{ padding:16, borderRadius:14, background:margin > 40 ? \"rgba(16,185,129,0.05)\" : \"rgba(245,158,11,0.05)\", border:`1px solid ${margin > 40 ? \"rgba(16,185,129,0.2)\" : \"rgba(245,158,11,0.2)\"}` }}>\n              <p style={{ fontSize:12, fontWeight:700, color:C.muted, margin:\"0 0 8px\" }}>Profit margin</p>\n              <p style={{ fontSize:24, fontWeight:900, color:margin > 40 ? V.green : V.amber, margin:\"0 0 4px\", letterSpacing:\"-0.04em\" }}>{margin}%</p>\n              <p style={{ fontSize:11, color:C.muted, margin:0 }}>\n                ₦{(Number(form.price) - Number(form.costPrice)).toLocaleString()} profit per sale\n              </p>\n            </div>\n          )}\n        </div>\n      </div>\n\n      <style>{`\n        @keyframes spin{to{transform:rotate(360deg)}}\n        @media(max-width:768px){ .edit-grid{grid-template-columns:1fr!important;} .stats-row{grid-template-columns:1fr 1fr!important;} }\n      `}</style>\n    </div>\n  );\n}\n","frontend/src/app/dashboard/orders/[orderId]/page.tsx":"\"use client\";\nimport { useState } from \"react\";\nimport { useParams, useRouter } from \"next/navigation\";\nimport { useQuery, useMutation, useQueryClient } from \"@tanstack/react-query\";\nimport { motion } from \"framer-motion\";\nimport { useTheme } from \"../../../../components/layout/DashboardLayout\";\nimport { useAuthStore } from \"../../../../store/auth.store\";\nimport { api } from \"../../../../lib/api\";\nimport toast from \"react-hot-toast\";\nimport Link from \"next/link\";\nimport {\n  ArrowLeft, Package, Truck, Check, Clock, X, RefreshCw,\n  MapPin, Phone, Mail, User, Copy, ExternalLink, MessageSquare,\n} from \"lucide-react\";\n\nconst V = { v500:\"#6B35E8\", v400:\"#8B5CF6\", green:\"#10B981\", amber:\"#F59E0B\", red:\"#EF4444\", cyan:\"#06B6D4\" };\n\nconst STATUS_CONFIG: Record<string,any> = {\n  PENDING:    { label:\"Pending\",    color:V.amber,  bg:\"rgba(245,158,11,0.1)\",  icon:Clock,   next:\"PAID\" },\n  PAID:       { label:\"Paid\",       color:V.green,  bg:\"rgba(16,185,129,0.1)\",  icon:Check,   next:\"SHIPPED\" },\n  SHIPPED:    { label:\"Shipped\",    color:V.cyan,   bg:\"rgba(6,182,212,0.1)\",   icon:Truck,   next:\"DELIVERED\" },\n  DELIVERED:  { label:\"Delivered\",  color:V.v400,   bg:\"rgba(107,53,232,0.1)\", icon:Package, next:null },\n  CANCELLED:  { label:\"Cancelled\",  color:V.red,    bg:\"rgba(239,68,68,0.1)\",   icon:X,       next:null },\n  REFUNDED:   { label:\"Refunded\",   color:V.v400,   bg:\"rgba(139,92,246,0.1)\", icon:RefreshCw,next:null },\n};\n\nconst TIMELINE_STEPS = [\"PENDING\",\"PAID\",\"SHIPPED\",\"DELIVERED\"];\n\nexport default function OrderDetailPage() {\n  const { orderId } = useParams<{ orderId:string }>();\n  const router = useRouter();\n  const qc = useQueryClient();\n  const { theme } = useTheme();\n  const isDark = theme === \"dark\";\n  const storeId = useAuthStore(s => s.user?.stores?.[0]?.id);\n\n  const C = {\n    card:   isDark ? \"rgba(255,255,255,0.04)\" : \"#fff\",\n    text:   isDark ? \"#F0ECFF\" : \"#130D2E\",\n    muted:  isDark ? \"rgba(240,236,255,0.45)\" : \"rgba(19,13,46,0.5)\",\n    border: isDark ? \"rgba(107,53,232,0.15)\" : \"rgba(107,53,232,0.12)\",\n    faint:  isDark ? \"rgba(107,53,232,0.06)\" : \"rgba(107,53,232,0.04)\",\n  };\n\n  const [tracking, setTracking] = useState(\"\");\n\n  const { data: order, isLoading } = useQuery({\n    queryKey: [\"order\", orderId],\n    queryFn: () => api.get(`/orders/${storeId}/${orderId}`).then(r => r.data.data),\n    enabled: !!storeId && !!orderId,\n  });\n\n  const updateMut = useMutation({\n    mutationFn: (status: string) => api.put(`/orders/${storeId}/${orderId}`, { status, trackingNumber: tracking || undefined }),\n    onSuccess: (_, status) => { toast.success(`Order marked as ${status}`); qc.invalidateQueries({ queryKey:[\"order\", orderId] }); qc.invalidateQueries({ queryKey:[\"orders\"] }); },\n    onError: () => toast.error(\"Update failed\"),\n  });\n\n  if (isLoading || !order) return (\n    <div style={{ display:\"flex\", alignItems:\"center\", justifyContent:\"center\", height:400 }}>\n      <RefreshCw size={24} color={V.v400} style={{ animation:\"spin 0.7s linear infinite\" }}/>\n      <style>{\"@keyframes spin{to{transform:rotate(360deg)}}\"}</style>\n    </div>\n  );\n\n  const cfg = STATUS_CONFIG[order.status] || STATUS_CONFIG.PENDING;\n  const Icon = cfg.icon;\n  const currentStep = TIMELINE_STEPS.indexOf(order.status);\n  const fmt = (n: number) => `₦${Number(n||0).toLocaleString()}`;\n\n  return (\n    <div style={{ maxWidth:840, margin:\"0 auto\", fontFamily:\"'Plus Jakarta Sans',system-ui,sans-serif\" }}>\n      {/* Header */}\n      <div style={{ display:\"flex\", alignItems:\"center\", justifyContent:\"space-between\", marginBottom:24, flexWrap:\"wrap\", gap:12 }}>\n        <div style={{ display:\"flex\", alignItems:\"center\", gap:12 }}>\n          <Link href=\"/dashboard/orders\" style={{ width:36, height:36, borderRadius:10, background:C.card, border:`1px solid ${C.border}`, display:\"flex\", alignItems:\"center\", justifyContent:\"center\", textDecoration:\"none\", color:C.muted }}>\n            <ArrowLeft size={16}/>\n          </Link>\n          <div>\n            <h1 style={{ fontSize:18, fontWeight:900, color:C.text, margin:0 }}>Order #{order.orderNumber || orderId?.slice(-8).toUpperCase()}</h1>\n            <p style={{ fontSize:12, color:C.muted, margin:0 }}>{new Date(order.createdAt).toLocaleString(\"en-NG\", { day:\"numeric\", month:\"long\", year:\"numeric\", hour:\"2-digit\", minute:\"2-digit\" })}</p>\n          </div>\n        </div>\n        <div style={{ display:\"flex\", alignItems:\"center\", gap:8, padding:\"8px 16px\", borderRadius:99, background:cfg.bg, border:`1px solid ${cfg.color}30` }}>\n          <Icon size={14} color={cfg.color}/>\n          <span style={{ fontSize:13, fontWeight:700, color:cfg.color }}>{cfg.label}</span>\n        </div>\n      </div>\n\n      {/* Timeline */}\n      {![\"CANCELLED\",\"REFUNDED\"].includes(order.status) && (\n        <div style={{ background:C.card, borderRadius:16, padding:\"20px 24px\", border:`1px solid ${C.border}`, marginBottom:16 }}>\n          <div style={{ display:\"flex\", alignItems:\"center\", gap:0 }}>\n            {TIMELINE_STEPS.map((step, i) => {\n              const done = currentStep >= i;\n              const active = currentStep === i;\n              const stepCfg = STATUS_CONFIG[step];\n              const StepIcon = stepCfg.icon;\n              return (\n                <div key={step} style={{ display:\"flex\", alignItems:\"center\", flex: i < TIMELINE_STEPS.length-1 ? 1 : 0 }}>\n                  <div style={{ display:\"flex\", flexDirection:\"column\", alignItems:\"center\", gap:6 }}>\n                    <div style={{ width:36, height:36, borderRadius:\"50%\", background:done?V.v500:\"transparent\", border:`2px solid ${done?V.v500:C.border}`, display:\"flex\", alignItems:\"center\", justifyContent:\"center\", transition:\"all 0.3s\", boxShadow:active?`0 0 0 4px ${V.v500}20`:undefined }}>\n                      <StepIcon size={15} color={done?\"#fff\":C.muted as string}/>\n                    </div>\n                    <p style={{ fontSize:10, fontWeight:done?700:400, color:done?C.text:C.muted, margin:0, whiteSpace:\"nowrap\" }}>{stepCfg.label}</p>\n                  </div>\n                  {i < TIMELINE_STEPS.length-1 && (\n                    <div style={{ flex:1, height:2, background:currentStep > i ? V.v500 : C.border, margin:\"0 8px\", marginBottom:18, transition:\"all 0.3s\" }}/>\n                  )}\n                </div>\n              );\n            })}\n          </div>\n        </div>\n      )}\n\n      <div style={{ display:\"grid\", gridTemplateColumns:\"1fr 280px\", gap:16 }} className=\"order-grid\">\n        {/* Left */}\n        <div style={{ display:\"flex\", flexDirection:\"column\", gap:14 }}>\n          {/* Items */}\n          <div style={{ background:C.card, borderRadius:16, padding:20, border:`1px solid ${C.border}` }}>\n            <p style={{ fontSize:13, fontWeight:700, color:C.text, margin:\"0 0 14px\" }}>{order.items?.length || 0} item{order.items?.length !== 1 ? \"s\" : \"\"}</p>\n            {(order.items || []).map((item: any, i: number) => (\n              <div key={i} style={{ display:\"flex\", gap:12, marginBottom:i < order.items.length-1 ? 12 : 0, paddingBottom:i < order.items.length-1 ? 12 : 0, borderBottom:i < order.items.length-1 ? `1px solid ${C.border}` : \"none\" }}>\n                {item.image ? (\n                  <img src={item.image} alt={item.name} style={{ width:52, height:52, borderRadius:10, objectFit:\"cover\", flexShrink:0, background:C.faint }}/>\n                ) : (\n                  <div style={{ width:52, height:52, borderRadius:10, background:C.faint, display:\"flex\", alignItems:\"center\", justifyContent:\"center\", flexShrink:0 }}>\n                    <Package size={20} color={C.muted as string}/>\n                  </div>\n                )}\n                <div style={{ flex:1 }}>\n                  <p style={{ fontSize:13, fontWeight:600, color:C.text, margin:\"0 0 2px\" }}>{item.name}</p>\n                  {item.variant && <p style={{ fontSize:11, color:C.muted, margin:\"0 0 4px\" }}>{item.variant}</p>}\n                  <p style={{ fontSize:12, color:C.muted, margin:0 }}>Qty: {item.quantity} × {fmt(item.price)}</p>\n                </div>\n                <p style={{ fontSize:14, fontWeight:700, color:C.text, flexShrink:0 }}>{fmt(item.quantity * item.price)}</p>\n              </div>\n            ))}\n          </div>\n\n          {/* Totals */}\n          <div style={{ background:C.card, borderRadius:16, padding:20, border:`1px solid ${C.border}` }}>\n            {[\n              { label:\"Subtotal\",  value:fmt(order.subtotal || order.total) },\n              { label:\"Shipping\",  value:order.shippingCost ? fmt(order.shippingCost) : \"Free\" },\n              { label:\"Discount\",  value:order.discount ? `-${fmt(order.discount)}` : null },\n            ].filter(r => r.value).map(row => (\n              <div key={row.label} style={{ display:\"flex\", justifyContent:\"space-between\", marginBottom:8 }}>\n                <span style={{ fontSize:13, color:C.muted }}>{row.label}</span>\n                <span style={{ fontSize:13, color:C.text }}>{row.value}</span>\n              </div>\n            ))}\n            <div style={{ display:\"flex\", justifyContent:\"space-between\", paddingTop:12, borderTop:`1px solid ${C.border}`, marginTop:4 }}>\n              <span style={{ fontSize:15, fontWeight:700, color:C.text }}>Total</span>\n              <span style={{ fontSize:18, fontWeight:900, color:C.text, letterSpacing:\"-0.03em\" }}>{fmt(order.total)}</span>\n            </div>\n          </div>\n\n          {/* Fulfillment actions */}\n          {cfg.next && (\n            <div style={{ background:C.card, borderRadius:16, padding:20, border:`1px solid ${C.border}` }}>\n              <p style={{ fontSize:13, fontWeight:700, color:C.text, margin:\"0 0 14px\" }}>Fulfil this order</p>\n              {cfg.next === \"SHIPPED\" && (\n                <div style={{ marginBottom:12 }}>\n                  <label style={{ fontSize:12, fontWeight:700, color:C.muted, display:\"block\", marginBottom:5 }}>Tracking number (optional)</label>\n                  <input value={tracking} onChange={e => setTracking(e.target.value)}\n                    placeholder=\"e.g. GIG-12345678\" style={{ width:\"100%\", padding:\"10px 14px\", borderRadius:10, border:`1px solid ${C.border}`, background:C.faint, color:C.text, fontSize:13, fontFamily:\"inherit\", outline:\"none\" }}/>\n                </div>\n              )}\n              <button onClick={() => updateMut.mutate(cfg.next)} disabled={updateMut.isPending}\n                style={{ width:\"100%\", padding:\"13px 0\", borderRadius:12, border:\"none\", cursor:\"pointer\", background:`linear-gradient(135deg,#2D1B69,${V.v500})`, color:\"#fff\", fontSize:14, fontWeight:700, fontFamily:\"inherit\", display:\"flex\", alignItems:\"center\", justifyContent:\"center\", gap:8, boxShadow:\"0 4px 16px rgba(107,53,232,0.25)\", opacity:updateMut.isPending?0.7:1 }}>\n                {updateMut.isPending ? <><RefreshCw size={14} style={{ animation:\"spin 0.7s linear infinite\" }}/> Updating…</>\n                  : cfg.next === \"SHIPPED\" ? <><Truck size={14}/> Mark as Shipped</>\n                  : cfg.next === \"DELIVERED\" ? <><Check size={14}/> Mark as Delivered</>\n                  : <><Check size={14}/> Mark as {STATUS_CONFIG[cfg.next]?.label}</>\n                }\n              </button>\n              {![\"CANCELLED\",\"DELIVERED\"].includes(order.status) && (\n                <button onClick={() => updateMut.mutate(\"CANCELLED\")}\n                  style={{ width:\"100%\", marginTop:8, padding:\"10px 0\", borderRadius:10, border:`1px solid ${V.red}20`, background:\"rgba(239,68,68,0.05)\", color:V.red, cursor:\"pointer\", fontSize:13, fontWeight:600, fontFamily:\"inherit\" }}>\n                  Cancel order\n                </button>\n              )}\n            </div>\n          )}\n        </div>\n\n        {/* Right sidebar */}\n        <div style={{ display:\"flex\", flexDirection:\"column\", gap:12 }}>\n          {/* Customer */}\n          <div style={{ background:C.card, borderRadius:16, padding:18, border:`1px solid ${C.border}` }}>\n            <p style={{ fontSize:12, fontWeight:700, color:C.muted, margin:\"0 0 12px\", textTransform:\"uppercase\", letterSpacing:\"0.08em\" }}>Customer</p>\n            <div style={{ display:\"flex\", alignItems:\"center\", gap:10, marginBottom:14 }}>\n              <div style={{ width:36, height:36, borderRadius:10, background:`${V.v500}15`, display:\"flex\", alignItems:\"center\", justifyContent:\"center\", flexShrink:0 }}>\n                <User size={16} color={V.v400}/>\n              </div>\n              <div>\n                <p style={{ fontSize:13, fontWeight:700, color:C.text, margin:0 }}>{order.customerName || \"Guest\"}</p>\n                <p style={{ fontSize:11, color:C.muted, margin:0 }}>{order.customerEmail}</p>\n              </div>\n            </div>\n            <div style={{ display:\"flex\", flexDirection:\"column\", gap:8 }}>\n              {order.customerPhone && (\n                <div style={{ display:\"flex\", gap:8 }}>\n                  <Phone size={13} color={C.muted as string} style={{ flexShrink:0, marginTop:2 }}/>\n                  <a href={`tel:${order.customerPhone}`} style={{ fontSize:13, color:C.text, textDecoration:\"none\" }}>{order.customerPhone}</a>\n                </div>\n              )}\n              <div style={{ display:\"flex\", gap:8 }}>\n                <Mail size={13} color={C.muted as string} style={{ flexShrink:0, marginTop:2 }}/>\n                <a href={`mailto:${order.customerEmail}`} style={{ fontSize:13, color:V.v400, textDecoration:\"none\" }}>{order.customerEmail}</a>\n              </div>\n            </div>\n            {order.customerPhone && (\n              <a href={`https://wa.me/${order.customerPhone?.replace(/\\D/g,\"\")}`} target=\"_blank\" rel=\"noreferrer\"\n                style={{ display:\"flex\", alignItems:\"center\", justifyContent:\"center\", gap:8, marginTop:12, padding:\"9px 0\", borderRadius:10, background:\"rgba(37,211,102,0.08)\", border:\"1px solid rgba(37,211,102,0.2)\", color:\"#25D366\", textDecoration:\"none\", fontSize:13, fontWeight:700 }}>\n                <MessageSquare size={13}/> WhatsApp customer\n              </a>\n            )}\n          </div>\n\n          {/* Shipping address */}\n          {order.shippingAddress && (\n            <div style={{ background:C.card, borderRadius:16, padding:18, border:`1px solid ${C.border}` }}>\n              <p style={{ fontSize:12, fontWeight:700, color:C.muted, margin:\"0 0 12px\", textTransform:\"uppercase\", letterSpacing:\"0.08em\" }}>Shipping address</p>\n              <div style={{ display:\"flex\", gap:8 }}>\n                <MapPin size={13} color={C.muted as string} style={{ flexShrink:0, marginTop:2 }}/>\n                <div>\n                  <p style={{ fontSize:13, color:C.text, margin:0, lineHeight:1.6 }}>\n                    {order.shippingAddress.street}<br/>\n                    {order.shippingAddress.city}{order.shippingAddress.state ? `, ${order.shippingAddress.state}` : \"\"}<br/>\n                    {order.shippingAddress.country || \"Nigeria\"}\n                  </p>\n                </div>\n              </div>\n            </div>\n          )}\n\n          {/* Payment */}\n          <div style={{ background:C.card, borderRadius:16, padding:18, border:`1px solid ${C.border}` }}>\n            <p style={{ fontSize:12, fontWeight:700, color:C.muted, margin:\"0 0 12px\", textTransform:\"uppercase\", letterSpacing:\"0.08em\" }}>Payment</p>\n            <div style={{ display:\"flex\", justifyContent:\"space-between\", marginBottom:6 }}>\n              <span style={{ fontSize:12, color:C.muted }}>Method</span>\n              <span style={{ fontSize:12, fontWeight:600, color:C.text }}>{order.paymentMethod || \"Paystack\"}</span>\n            </div>\n            <div style={{ display:\"flex\", justifyContent:\"space-between\" }}>\n              <span style={{ fontSize:12, color:C.muted }}>Status</span>\n              <span style={{ fontSize:12, fontWeight:700, color:order.paymentStatus===\"PAID\"?V.green:V.amber }}>{order.paymentStatus || \"Pending\"}</span>\n            </div>\n          </div>\n\n          {/* Tracking */}\n          {order.trackingNumber && (\n            <div style={{ padding:14, borderRadius:14, background:`${V.cyan}08`, border:`1px solid ${V.cyan}20` }}>\n              <p style={{ fontSize:11, fontWeight:700, color:V.cyan, margin:\"0 0 6px\" }}>TRACKING</p>\n              <div style={{ display:\"flex\", alignItems:\"center\", gap:8 }}>\n                <code style={{ fontSize:13, fontWeight:700, color:C.text, flex:1 }}>{order.trackingNumber}</code>\n                <button onClick={() => { navigator.clipboard.writeText(order.trackingNumber); toast.success(\"Copied\"); }}\n                  style={{ background:\"none\", border:\"none\", cursor:\"pointer\", color:V.cyan, padding:4 }}>\n                  <Copy size={13}/>\n                </button>\n              </div>\n            </div>\n          )}\n        </div>\n      </div>\n\n      <style>{`\n        @keyframes spin{to{transform:rotate(360deg)}}\n        @media(max-width:768px){ .order-grid{grid-template-columns:1fr!important;} }\n      `}</style>\n    </div>\n  );\n}\n","frontend/src/app/dashboard/products/page.tsx":"\"use client\";\nimport Link from \"next/link\";\nimport { useState, useRef, useCallback } from \"react\";\nimport { useQuery, useMutation, useQueryClient } from \"@tanstack/react-query\";\nimport { motion, AnimatePresence } from \"framer-motion\";\nimport { useTheme } from \"../../../components/layout/DashboardLayout\";\nimport { useAuthStore } from \"../../../store/auth.store\";\nimport { api, uploadAPI } from \"../../../lib/api\";\nimport { useCurrency } from \"../../../lib/currency\";\nimport {\n  Package, Plus, Search, Edit2, Trash2, X, Loader2, Upload,\n  ImageIcon, Star, ChevronDown, Zap, Filter, Check, AlertCircle\n} from \"lucide-react\";\nimport toast from \"react-hot-toast\";\n\nconst V = { v500:\"#6B35E8\", v400:\"#8B5CF6\", v300:\"#A78BFA\", green:\"#10B981\", amber:\"#F59E0B\", red:\"#EF4444\" };\n\n// ── Image Uploader (inline, fully styled) ─────────────────────────────────────\nfunction ImageUploader({ images, onChange, maxImages=8, t, isDark }: any) {\n  const [uploading, setUploading] = useState<string[]>([]);\n  const [drag, setDrag] = useState(false);\n  const [err, setErr] = useState(\"\");\n  const ref = useRef<HTMLInputElement>(null);\n\n  const upload = useCallback(async (files: FileList | File[]) => {\n    const arr = Array.from(files).slice(0, maxImages - images.length);\n    if (!arr.length) return;\n    setErr(\"\");\n    for (const file of arr) {\n      if (file.type && !file.type.startsWith(\"image/\")) { setErr(\"Only image files allowed\"); continue; }\n      if (file.size > 10 * 1024 * 1024) { setErr(\"Max 10MB per image\"); continue; }\n      setUploading(p => [...p, file.name]);\n      try {\n        const res = await uploadAPI.image(file);\n        // uploadAPI uses fetch (not axios) so backend {success,data:{url}} is returned directly\n        const url = (res as any)?.data?.url   // normal: {success:true, data:{url}}\n                 || (res as any)?.data?.data?.url  // legacy double-wrapped\n                 || (res as any)?.url;         // fallback\n        if (!url) throw new Error(\"Upload succeeded but no URL returned — check server logs\");\n        onChange([...images, url]);\n      } catch {\n        setErr(\"Upload failed — please try again or use a different image format\");\n      setTimeout(() => setErr(\"\"), 4000);\n      } finally {\n        setUploading(p => p.filter(n => n !== file.name));\n      }\n    }\n  }, [images, maxImages, onChange]);\n\n  const isUp = uploading.length > 0;\n\n  return (\n    <div>\n      {/* Existing images grid */}\n      {images.length > 0 && (\n        <div style={{ display:\"grid\", gridTemplateColumns:\"repeat(4,1fr)\", gap:10, marginBottom:10 }}>\n          {images.map((url: string, i: number) => (\n            <div key={url} style={{ position:\"relative\", aspectRatio:\"1\", borderRadius:12, overflow:\"hidden\", background:t.faint }}>\n              <img src={url} alt=\"\" style={{ width:\"100%\", height:\"100%\", objectFit:\"cover\" }}/>\n              {i===0 && (\n                <div style={{ position:\"absolute\", top:6, left:6, background:V.v500, color:\"#fff\", fontSize:9, fontWeight:700, padding:\"2px 8px\", borderRadius:99 }}>MAIN</div>\n              )}\n              <div style={{ position:\"absolute\", inset:0, background:\"rgba(0,0,0,0.5)\", opacity:0, transition:\"opacity 0.15s\", display:\"flex\", alignItems:\"center\", justifyContent:\"center\", gap:6 }}\n                onMouseEnter={e=>(e.currentTarget.style.opacity=\"1\")} onMouseLeave={e=>(e.currentTarget.style.opacity=\"0\")}>\n                {i!==0 && (\n                  <button onClick={()=>{const a=[...images];a.splice(i,1);a.unshift(url);onChange(a);}}\n                    style={{ width:28,height:28,borderRadius:8,background:\"rgba(255,255,255,0.2)\",border:\"none\",cursor:\"pointer\",display:\"flex\",alignItems:\"center\",justifyContent:\"center\" }}\n                    title=\"Set as main\">\n                    <Star size={12} color=\"#fff\"/>\n                  </button>\n                )}\n                <button onClick={()=>onChange(images.filter((_:string,j:number)=>j!==i))}\n                  style={{ width:28,height:28,borderRadius:8,background:\"rgba(239,68,68,0.8)\",border:\"none\",cursor:\"pointer\",display:\"flex\",alignItems:\"center\",justifyContent:\"center\" }}>\n                  <X size={12} color=\"#fff\"/>\n                </button>\n              </div>\n            </div>\n          ))}\n          {images.length < maxImages && (\n            <button onClick={()=>ref.current?.click()} type=\"button\"\n              style={{ aspectRatio:\"1\",borderRadius:12,border:`2px dashed ${drag?V.v400:t.border}`,background:t.faint,cursor:\"pointer\",display:\"flex\",flexDirection:\"column\",alignItems:\"center\",justifyContent:\"center\",gap:4,color:t.muted,transition:\"all 0.15s\" }}\n              onDragOver={e=>{e.preventDefault();setDrag(true)}} onDragLeave={()=>setDrag(false)}\n              onDrop={e=>{e.preventDefault();setDrag(false);upload(e.dataTransfer.files)}}>\n              {isUp?<Loader2 size={16} style={{animation:\"spin 0.8s linear infinite\",color:V.v400}}/>:<><Upload size={14}/><span style={{fontSize:10,fontWeight:700}}>Add</span></>}\n            </button>\n          )}\n        </div>\n      )}\n\n      {/* Drop zone (empty state) */}\n      {images.length === 0 && (\n        <div\n          onClick={()=>ref.current?.click()}\n          onDragOver={e=>{e.preventDefault();setDrag(true)}} onDragLeave={()=>setDrag(false)}\n          onDrop={e=>{e.preventDefault();setDrag(false);upload(e.dataTransfer.files)}}\n          style={{ padding:\"32px 20px\",borderRadius:16,border:`2px dashed ${drag?V.v400:t.border}`,background:drag?`${V.v400}08`:t.faint,cursor:\"pointer\",textAlign:\"center\",transition:\"all 0.2s\" }}>\n          {isUp ? (\n            <div style={{ display:\"flex\",flexDirection:\"column\",alignItems:\"center\",gap:10 }}>\n              <Loader2 size={28} style={{ color:V.v400,animation:\"spin 0.8s linear infinite\" }}/>\n              <p style={{ fontSize:13,color:t.muted,margin:0 }}>Uploading {uploading.length} image{uploading.length>1?\"s\":\"\"}…</p>\n            </div>\n          ) : (\n            <div style={{ display:\"flex\",flexDirection:\"column\",alignItems:\"center\",gap:10 }}>\n              <div style={{ width:52,height:52,borderRadius:16,background:`${V.v400}15`,display:\"flex\",alignItems:\"center\",justifyContent:\"center\" }}>\n                <ImageIcon size={22} color={V.v400}/>\n              </div>\n              <div>\n                <p style={{ fontSize:14,fontWeight:700,color:t.text,margin:\"0 0 4px\" }}>\n                  Drop images here or <span style={{ color:V.v400 }}>browse</span>\n                </p>\n                <p style={{ fontSize:12,color:t.muted,margin:0 }}>\n                  All image formats · Max 10MB · Up to {maxImages} images\n                </p>\n              </div>\n              <div style={{ display:\"flex\",alignItems:\"center\",gap:6,padding:\"8px 16px\",borderRadius:10,background:`linear-gradient(135deg,${V.v500},#3D1C8A)`,cursor:\"pointer\" }}>\n                <Upload size={13} color=\"#fff\"/>\n                <span style={{ fontSize:13,fontWeight:700,color:\"#fff\" }}>Choose Photos</span>\n              </div>\n            </div>\n          )}\n        </div>\n      )}\n\n      {err && (\n        <div style={{ display:\"flex\",alignItems:\"center\",gap:8,padding:\"8px 12px\",borderRadius:10,background:\"rgba(239,68,68,0.08)\",border:\"1px solid rgba(239,68,68,0.2)\",marginTop:8 }}>\n          <AlertCircle size={13} color={V.red} style={{ flexShrink:0 }}/>\n          <p style={{ fontSize:12,color:V.red,margin:0 }}>{err}</p>\n          <button onClick={()=>setErr(\"\")} style={{ marginLeft:\"auto\",background:\"none\",border:\"none\",cursor:\"pointer\",color:V.red,display:\"flex\" }}><X size={12}/></button>\n        </div>\n      )}\n\n      <p style={{ fontSize:11,color:t.muted,marginTop:6 }}>\n        {images.length}/{maxImages} images · First image is the main display image\n      </p>\n      <input ref={ref} type=\"file\" accept=\"image/*,image/heic,image/heif\" multiple style={{ display:\"none\" }}\n        onChange={e=>{if(e.target.files)upload(e.target.files);e.target.value=\"\";}}/>\n      <style>{`@keyframes spin{to{transform:rotate(360deg)}}`}</style>\n    </div>\n  );\n}\n\n// ── Product Modal ─────────────────────────────────────────────────────────────\nfunction ProductModal({ storeId, product, onClose, t, isDark }: any) {\n  const { fmt } = useCurrency();\n  const qc = useQueryClient();\n  const isEdit = !!product?.id;\n\n  const [form, setForm] = useState({\n    name:          product?.name          || \"\",\n    description:   product?.description   || \"\",\n    price:         product?.price?.toString()         || \"\",\n    comparePrice:  product?.comparePrice?.toString()  || \"\",\n    costPrice:     product?.costPrice?.toString()     || \"\",\n    inventory:     product?.inventory?.toString()     || \"0\",\n    category:      product?.category      || \"\",\n    status:        product?.status        || \"ACTIVE\",\n    images:        product?.images        || [] as string[],\n    sku:           product?.sku           || \"\",\n    weight:        product?.weight?.toString()        || \"\",\n  });\n\n  const mut = useMutation({\n    mutationFn: () => {\n      const payload = {\n        name:        form.name,\n        description: form.description,\n        price:       parseFloat(form.price),\n        comparePrice: form.comparePrice ? parseFloat(form.comparePrice) : null,\n        costPrice:   form.costPrice ? parseFloat(form.costPrice) : null,\n        inventory:   parseInt(form.inventory),\n        category:    form.category,\n        status:      form.status,\n        images:      form.images,\n        sku:         form.sku,\n        weight:      form.weight ? parseFloat(form.weight) : null,\n      };\n      return isEdit\n        ? api.put(`/products/${storeId}/${product.id}`, payload)\n        : api.post(`/products/${storeId}`, payload);\n    },\n    onSuccess: () => {\n      toast.success(isEdit ? \"Product updated!\" : \"Product created!\");\n      qc.invalidateQueries({ queryKey: [\"products\"] });\n      onClose();\n    },\n    onError: (e: any) => toast.error(e.response?.data?.message || \"Failed to save\"),\n  });\n\n  const inp = {\n    width:\"100%\", padding:\"10px 14px\", borderRadius:12,\n    border:`1px solid ${t.border}`, background:isDark?\"rgba(255,255,255,0.05)\":\"#F0EDFF\",\n    color:t.text, fontSize:13, outline:\"none\", fontFamily:\"inherit\", boxSizing:\"border-box\" as const,\n  };\n\n  const label = (txt: string) => (\n    <label style={{ display:\"block\", fontSize:11, fontWeight:700, color:t.muted, marginBottom:6, textTransform:\"uppercase\" as const, letterSpacing:\"0.08em\" }}>\n      {txt}\n    </label>\n  );\n\n  return (\n    <div style={{ position:\"fixed\",inset:0,zIndex:50,display:\"flex\",alignItems:\"flex-start\",justifyContent:\"center\",padding:\"20px 16px\",background:\"rgba(0,0,0,0.6)\",backdropFilter:\"blur(8px)\",overflowY:\"auto\" }}\n      onClick={e=>e.target===e.currentTarget&&onClose()}>\n      <motion.div initial={{opacity:0,scale:0.96,y:20}} animate={{opacity:1,scale:1,y:0}} exit={{opacity:0,scale:0.96}}\n        style={{ width:\"100%\",maxWidth:680,borderRadius:20,overflow:\"hidden\",background:isDark?\"#0F0B1E\":\"#fff\",border:`1px solid ${t.border}`,marginTop:20 }}>\n\n        {/* Header */}\n        <div style={{ display:\"flex\",alignItems:\"center\",justifyContent:\"space-between\",padding:\"18px 24px\",borderBottom:`1px solid ${t.border}` }}>\n          <div>\n            <h3 style={{ fontSize:16,fontWeight:900,color:t.text,margin:\"0 0 2px\" }}>\n              {isEdit ? \"Edit Product\" : \"Add New Product\"}\n            </h3>\n            <p style={{ fontSize:12,color:t.muted,margin:0 }}>\n              {isEdit ? \"Update product details\" : \"Fill in the details to add a product to your store\"}\n            </p>\n          </div>\n          <button onClick={onClose} style={{ border:\"none\",background:t.faint,cursor:\"pointer\",color:t.muted,width:32,height:32,borderRadius:10,display:\"flex\",alignItems:\"center\",justifyContent:\"center\" }}>\n            <X size={16}/>\n          </button>\n        </div>\n\n        <div style={{ padding:\"24px\",maxHeight:\"80vh\",overflowY:\"auto\" }}>\n          {/* Images */}\n          <div style={{ marginBottom:20 }}>\n            <label style={{ display:\"block\",fontSize:11,fontWeight:700,color:t.muted,marginBottom:10,textTransform:\"uppercase\" as const,letterSpacing:\"0.08em\" }}>\n              Product Images *\n            </label>\n            <ImageUploader\n              images={form.images}\n              onChange={(imgs: string[]) => setForm(f=>({...f, images:imgs}))}\n              t={t} isDark={isDark}\n            />\n          </div>\n\n          {/* Name + Category */}\n          <div style={{ display:\"grid\",gridTemplateColumns:\"1fr 1fr\",gap:14,marginBottom:14 }}>\n            <div>\n              {label(\"Product Name *\")}\n              <input style={inp} value={form.name} onChange={e=>setForm(f=>({...f,name:e.target.value}))} placeholder=\"e.g. Premium Hair Bundle 18 inch\"/>\n            </div>\n            <div>\n              {label(\"Category\")}\n              <input style={inp} value={form.category} onChange={e=>setForm(f=>({...f,category:e.target.value}))} placeholder=\"e.g. Hair, Electronics, Beauty\"/>\n            </div>\n          </div>\n\n          {/* Description */}\n          <div style={{ marginBottom:14 }}>\n            <div style={{ display:\"flex\", alignItems:\"center\", justifyContent:\"space-between\", marginBottom:6 }}>\n              {label(\"Description\")}\n              <button type=\"button\"\n                disabled={!form.name || genDesc}\n                onClick={async () => {\n                  if (!form.name || genDesc) return;\n                  setGenDesc(true);\n                  try {\n                    const r = await api.post(\"/kai/smart-chat\", {\n                      storeId,\n                      message: `Write a compelling product description for: \"${form.name}\". ${form.category ? `Category: ${form.category}.` : \"\"} ${form.price ? `Price: ₦${form.price}.` : \"\"} Keep it 2-3 sentences, focus on benefits and why Nigerian buyers would want it. No bullets, no markdown, just clean flowing text.`,\n                    });\n                    const desc = r.data?.data?.message || r.data?.message || \"\";\n                    if (desc) setForm(f => ({ ...f, description: desc.replace(/\\*\\*/g, \"\").trim() }));\n                  } catch { toast.error(\"KIRO couldn't generate — try again\"); }\n                  finally { setGenDesc(false); }\n                }}\n                style={{ display:\"flex\", alignItems:\"center\", gap:5, padding:\"4px 10px\", borderRadius:8, border:`1px solid ${V.v400}30`, background:`${V.v400}10`, color:V.v400, fontSize:11, fontWeight:700, cursor: form.name ? \"pointer\" : \"not-allowed\", opacity: form.name ? 1 : 0.4, fontFamily:\"inherit\" }}>\n                {genDesc ? <Loader2 size={10} style={{ animation:\"spin 0.8s linear infinite\" }}/> : <Zap size={10}/>}\n                {genDesc ? \"Writing…\" : \"KIRO Write\"}\n              </button>\n            </div>\n            <textarea style={{...inp,resize:\"none\",display:\"block\"}} rows={3}\n              value={form.description} onChange={e=>setForm(f=>({...f,description:e.target.value}))}\n              placeholder=\"Describe your product — what it is, who it's for, why they need it...\"/>\n          </div>\n\n          {/* Pricing */}\n          <div style={{ display:\"grid\",gridTemplateColumns:\"1fr 1fr 1fr\",gap:14,marginBottom:14 }}>\n            <div>\n              {label(\"Selling Price *\")}\n              <input style={inp} type=\"number\" value={form.price} onChange={e=>setForm(f=>({...f,price:e.target.value}))} placeholder=\"25000\"/>\n            </div>\n            <div>\n              {label(\"Compare Price\")}\n              <input style={inp} type=\"number\" value={form.comparePrice} onChange={e=>setForm(f=>({...f,comparePrice:e.target.value}))} placeholder=\"35000\"/>\n              <p style={{ fontSize:10,color:t.muted,margin:\"4px 0 0\" }}>Shows as crossed-out price</p>\n            </div>\n            <div>\n              {label(\"Cost Price\")}\n              <input style={inp} type=\"number\" value={form.costPrice} onChange={e=>setForm(f=>({...f,costPrice:e.target.value}))} placeholder=\"12000\"/>\n              <p style={{ fontSize:10,color:t.muted,margin:\"4px 0 0\" }}>For profit tracking only</p>\n            </div>\n          </div>\n\n          {/* Inventory + SKU + Weight */}\n          <div style={{ display:\"grid\",gridTemplateColumns:\"1fr 1fr 1fr\",gap:14,marginBottom:14 }}>\n            <div>\n              {label(\"Stock Quantity\")}\n              <input style={inp} type=\"number\" value={form.inventory} onChange={e=>setForm(f=>({...f,inventory:e.target.value}))} placeholder=\"100\"/>\n            </div>\n            <div>\n              {label(\"SKU\")}\n              <input style={inp} value={form.sku} onChange={e=>setForm(f=>({...f,sku:e.target.value}))} placeholder=\"PROD-001\"/>\n            </div>\n            <div>\n              {label(\"Weight (kg)\")}\n              <input style={inp} type=\"number\" step=\"0.1\" value={form.weight} onChange={e=>setForm(f=>({...f,weight:e.target.value}))} placeholder=\"0.5\"/>\n            </div>\n          </div>\n\n          {/* Status */}\n          <div style={{ marginBottom:20 }}>\n            {label(\"Status\")}\n            <select style={{...inp,cursor:\"pointer\"}} value={form.status} onChange={e=>setForm(f=>({...f,status:e.target.value}))}>\n              <option value=\"ACTIVE\">Active — Visible on your store</option>\n              <option value=\"DRAFT\">Draft — Hidden from customers</option>\n              <option value=\"ARCHIVED\">Archived — No longer available</option>\n            </select>\n          </div>\n\n          {/* Profit preview */}\n          {form.price && form.costPrice && (\n            <div style={{ padding:\"12px 14px\",borderRadius:12,background:`${V.green}08`,border:`1px solid ${V.green}25`,marginBottom:20,display:\"flex\",gap:16,flexWrap:\"wrap\" }}>\n              {[\n                { label:\"Selling Price\", val: parseFloat(form.price) },\n                { label:\"Cost Price\",    val: parseFloat(form.costPrice) },\n                { label:\"Profit\",        val: parseFloat(form.price)-parseFloat(form.costPrice) },\n                { label:\"Margin\",        val: null },\n              ].map(item => (\n                <div key={item.label}>\n                  <p style={{ fontSize:10,color:t.muted,margin:\"0 0 2px\",textTransform:\"uppercase\" as const,letterSpacing:\"0.08em\" }}>{item.label}</p>\n                  <p style={{ fontSize:14,fontWeight:800,color:item.label===\"Profit\"?V.green:t.text,margin:0 }}>\n                    {item.label===\"Margin\"\n                      ? `${Math.round((parseFloat(form.price)-parseFloat(form.costPrice))/parseFloat(form.price)*100)}%`\n                      : fmt(item.val!, true)}\n                  </p>\n                </div>\n              ))}\n            </div>\n          )}\n        </div>\n\n        {/* Footer */}\n        <div style={{ padding:\"16px 24px\",borderTop:`1px solid ${t.border}`,display:\"flex\",gap:10,alignItems:\"center\" }}>\n          <button onClick={onClose} style={{ padding:\"10px 20px\",borderRadius:12,border:`1px solid ${t.border}`,background:\"transparent\",cursor:\"pointer\",color:t.muted,fontSize:13,fontWeight:600,fontFamily:\"inherit\" }}>\n            Cancel\n          </button>\n          <div style={{ flex:1 }}/>\n          {isEdit && (\n            <p style={{ fontSize:11,color:t.muted }}>Last updated: {product.updatedAt ? new Date(product.updatedAt).toLocaleDateString() : \"—\"}</p>\n          )}\n          <button onClick={()=>mut.mutate()} disabled={!form.name||!form.price||mut.isPending}\n            style={{ display:\"flex\",alignItems:\"center\",gap:8,padding:\"10px 24px\",borderRadius:12,border:\"none\",background:`linear-gradient(135deg,${V.v500},#3D1C8A)`,cursor:!form.name||!form.price?\"not-allowed\":\"pointer\",color:\"#fff\",fontSize:13,fontWeight:700,fontFamily:\"inherit\",opacity:!form.name||!form.price?0.5:1 }}>\n            {mut.isPending?<Loader2 size={14} style={{animation:\"spin 0.8s linear infinite\"}}/>:<Check size={14}/>}\n            {mut.isPending?\"Saving…\":isEdit?\"Save Changes\":\"Add Product\"}\n          </button>\n        </div>\n      </motion.div>\n    </div>\n  );\n}\n\n// ── Main Products Page ────────────────────────────────────────────────────────\nconst STATUSES = [\"ALL\",\"ACTIVE\",\"DRAFT\",\"ARCHIVED\"];\n\nexport default function ProductsPage() {\n  const { theme } = useTheme();\n  const isDark = theme === \"dark\";\n  const t = {\n    card:   isDark?\"#181230\":\"#fff\",\n    border: isDark?\"rgba(255,255,255,0.07)\":\"rgba(107,53,232,0.08)\",\n    text:   isDark?\"#F0ECFF\":\"#130D2E\",\n    muted:  isDark?\"rgba(240,236,255,0.45)\":\"rgba(19,13,46,0.55)\",\n    faint:  isDark?\"rgba(255,255,255,0.03)\":\"rgba(107,53,232,0.03)\",\n  };\n  const storeId = useAuthStore(s => s.user?.stores?.[0]?.id);\n  const { fmt, symbol, code } = useCurrency();\n  const qc = useQueryClient();\n\n  const [search,    setSearch]    = useState(\"\");\n  const [status,    setStatus]    = useState(\"ALL\");\n  const [showModal, setShowModal] = useState(false);\n  const [editing,   setEditing]   = useState<any>(null);\n  const [genDesc,   setGenDesc]   = useState(false);\n\n  const { data, isLoading } = useQuery<any>({\n    queryKey: [\"products\", storeId, status],\n    queryFn: () => api.get(`/products/${storeId}`, { params: { status: status===\"ALL\"?undefined:status, limit:100 } }).then(r => r.data.data),\n    enabled: !!storeId,\n  });\n\n  const deleteMut = useMutation({\n    mutationFn: (id: string) => api.delete(`/products/${storeId}/${id}`),\n    onSuccess: () => { toast.success(\"Product deleted\"); qc.invalidateQueries({ queryKey:[\"products\"] }); },\n  });\n\n  const products = (data?.products || data || []).filter((p: any) =>\n    !search || p.name?.toLowerCase().includes(search.toLowerCase())\n  );\n\n  const statusColor = (s: string) =>\n    s===\"ACTIVE\"?\"#10B981\" : s===\"DRAFT\"?\"#F59E0B\" : \"#EF4444\";\n\n  return (\n    <div style={{ maxWidth:1100, margin:\"0 auto\" }}>\n      {/* Header */}\n      <motion.div initial={{opacity:0,y:-8}} animate={{opacity:1,y:0}}\n        style={{ display:\"flex\",alignItems:\"center\",justifyContent:\"space-between\",marginBottom:24,flexWrap:\"wrap\",gap:12 }}>\n        <div>\n          <h1 style={{ fontSize:22,fontWeight:900,letterSpacing:\"-0.04em\",color:t.text,margin:\"0 0 4px\" }}>Products</h1>\n          <p style={{ fontSize:13,color:t.muted,margin:0 }}>\n            {products.length} product{products.length!==1?\"s\":\"\"} · Prices in {code} {symbol}\n          </p>\n        </div>\n        <div style={{ display:\"flex\",gap:10 }}>\n          <button onClick={()=>{setEditing(null);setShowModal(true);}}\n            style={{ display:\"flex\",alignItems:\"center\",gap:6,padding:\"9px 18px\",borderRadius:12,background:`linear-gradient(135deg,${V.v500},#3D1C8A)`,border:\"none\",cursor:\"pointer\",color:\"#fff\",fontSize:13,fontWeight:700,fontFamily:\"inherit\" }}>\n            <Plus size={15}/> Add Product\n          </button>\n        </div>\n      </motion.div>\n\n      {/* Filters */}\n      <div style={{ display:\"flex\",alignItems:\"center\",gap:10,marginBottom:16,flexWrap:\"wrap\" }}>\n        <div style={{ flex:1,minWidth:200,display:\"flex\",alignItems:\"center\",gap:10,padding:\"9px 14px\",borderRadius:12,background:t.faint,border:`1px solid ${t.border}` }}>\n          <Search size={14} style={{ color:t.muted,flexShrink:0 }}/>\n          <input value={search} onChange={e=>setSearch(e.target.value)} placeholder=\"Search products…\"\n            style={{ flex:1,background:\"transparent\",border:\"none\",outline:\"none\",color:t.text,fontSize:13,fontFamily:\"inherit\" }}/>\n        </div>\n        <div style={{ display:\"flex\",gap:6 }}>\n          {STATUSES.map(s => (\n            <button key={s} onClick={()=>setStatus(s)}\n              style={{ padding:\"7px 14px\",borderRadius:10,border:`1px solid ${status===s?\"rgba(107,53,232,0.4)\":t.border}`,background:status===s?\"rgba(107,53,232,0.08)\":\"transparent\",cursor:\"pointer\",fontSize:12,fontWeight:600,color:status===s?V.v400:t.muted,fontFamily:\"inherit\" }}>\n              {s.charAt(0)+s.slice(1).toLowerCase()}\n            </button>\n          ))}\n        </div>\n      </div>\n\n      {/* Product grid */}\n      {isLoading ? (\n        <div style={{ textAlign:\"center\",padding:\"80px 0\",color:t.muted }}>\n          <Loader2 size={28} style={{ margin:\"0 auto 12px\",animation:\"spin 0.8s linear infinite\",color:V.v400 }}/>\n          <p>Loading products…</p>\n        </div>\n      ) : products.length === 0 ? (\n        <motion.div initial={{opacity:0}} animate={{opacity:1}}\n          style={{ textAlign:\"center\",padding:\"80px 20px\",borderRadius:20,background:t.faint,border:`1px solid ${t.border}` }}>\n          <Package size={48} style={{ color:t.muted,margin:\"0 auto 16px\" }}/>\n          <h3 style={{ fontSize:18,fontWeight:800,color:t.text,margin:\"0 0 8px\" }}>No products yet</h3>\n          <p style={{ fontSize:14,color:t.muted,margin:\"0 0 20px\",maxWidth:360,marginLeft:\"auto\",marginRight:\"auto\",lineHeight:1.6 }}>\n            Add your first product and it'll appear here. You can upload photos, set prices, and track inventory.\n          </p>\n          <button onClick={()=>{setEditing(null);setShowModal(true);}}\n            style={{ display:\"inline-flex\",alignItems:\"center\",gap:8,padding:\"11px 22px\",borderRadius:12,background:`linear-gradient(135deg,${V.v500},#3D1C8A)`,border:\"none\",cursor:\"pointer\",color:\"#fff\",fontSize:14,fontWeight:700,fontFamily:\"inherit\" }}>\n            <Plus size={15}/> Add Your First Product\n          </button>\n        </motion.div>\n      ) : (\n        <div style={{ display:\"grid\",gridTemplateColumns:\"repeat(auto-fill,minmax(220px,1fr))\",gap:14 }}>\n          {products.map((p: any, i: number) => {\n            const img = p.images?.[0];\n            const profit = p.costPrice ? p.price - p.costPrice : null;\n            const margin = profit && p.price ? Math.round(profit/p.price*100) : null;\n            return (\n              <motion.div key={p.id} initial={{opacity:0,y:12}} animate={{opacity:1,y:0}} transition={{delay:i*0.04}}\n                style={{ borderRadius:16,overflow:\"hidden\",background:t.card,border:`1px solid ${t.border}`,cursor:\"pointer\",transition:\"box-shadow 0.2s\" }}\n                onMouseEnter={e=>(e.currentTarget as HTMLElement).style.boxShadow=\"0 8px 24px rgba(107,53,232,0.12)\"}\n                onMouseLeave={e=>(e.currentTarget as HTMLElement).style.boxShadow=\"none\"}>\n\n                {/* Image */}\n                <div style={{ aspectRatio:\"1\",background:t.faint,position:\"relative\",overflow:\"hidden\" }}>\n                  {img\n                    ? <img src={img} alt={p.name} style={{ width:\"100%\",height:\"100%\",objectFit:\"cover\",transition:\"transform 0.3s\" }}\n                        onMouseEnter={e=>(e.target as HTMLImageElement).style.transform=\"scale(1.05)\"}\n                        onMouseLeave={e=>(e.target as HTMLImageElement).style.transform=\"scale(1)\"}/>\n                    : <div style={{ width:\"100%\",height:\"100%\",display:\"flex\",alignItems:\"center\",justifyContent:\"center\" }}>\n                        <Package size={28} style={{ color:t.muted }}/>\n                      </div>\n                  }\n                  {/* Status badge */}\n                  <div style={{ position:\"absolute\",top:8,left:8,background:statusColor(p.status),color:\"#fff\",fontSize:9,fontWeight:700,padding:\"2px 8px\",borderRadius:99 }}>\n                    {p.status}\n                  </div>\n                  {/* Image count */}\n                  {p.images?.length > 1 && (\n                    <div style={{ position:\"absolute\",bottom:8,right:8,background:\"rgba(0,0,0,0.6)\",color:\"#fff\",fontSize:10,fontWeight:700,padding:\"2px 8px\",borderRadius:99 }}>\n                      +{p.images.length-1}\n                    </div>\n                  )}\n                </div>\n\n                <div style={{ padding:\"12px 14px\" }}>\n                  <p style={{ fontSize:13,color:t.muted,margin:\"0 0 3px\",overflow:\"hidden\",textOverflow:\"ellipsis\",whiteSpace:\"nowrap\" }}>{p.category||\"—\"}</p>\n                  <p style={{ fontSize:14,fontWeight:700,color:t.text,margin:\"0 0 8px\",overflow:\"hidden\",textOverflow:\"ellipsis\",whiteSpace:\"nowrap\" }}>{p.name}</p>\n\n                  <div style={{ display:\"flex\",alignItems:\"center\",justifyContent:\"space-between\",marginBottom:10 }}>\n                    <div>\n                      <p style={{ fontSize:16,fontWeight:900,color:t.text,margin:0,letterSpacing:\"-0.03em\" }}>{fmt(p.price,true)}</p>\n                      {p.comparePrice && <p style={{ fontSize:11,color:t.muted,textDecoration:\"line-through\",margin:0 }}>{fmt(p.comparePrice,true)}</p>}\n                    </div>\n                    {margin !== null && (\n                      <span style={{ fontSize:10,fontWeight:700,color:V.green,background:\"rgba(16,185,129,0.1)\",padding:\"2px 8px\",borderRadius:99 }}>\n                        {margin}% margin\n                      </span>\n                    )}\n                  </div>\n\n                  <div style={{ display:\"flex\",alignItems:\"center\",justifyContent:\"space-between\" }}>\n                    <span style={{ fontSize:11,color:t.muted }}>\n                      {(p.inventory??p.stockQuantity??0).toLocaleString()} in stock\n                    </span>\n                    <div style={{ display:\"flex\",gap:6 }}>\n                      <button onClick={()=>{setEditing(p);setShowModal(true);}}\n                        style={{ width:28,height:28,borderRadius:8,border:`1px solid ${t.border}`,background:t.faint,cursor:\"pointer\",display:\"flex\",alignItems:\"center\",justifyContent:\"center\" }}>\n                        <Edit2 size={12} style={{ color:t.muted }}/>\n                      </button>\n                      <button onClick={()=>{if(confirm(\"Delete this product?\"))deleteMut.mutate(p.id);}}\n                        style={{ width:28,height:28,borderRadius:8,border:\"none\",background:\"rgba(239,68,68,0.08)\",cursor:\"pointer\",display:\"flex\",alignItems:\"center\",justifyContent:\"center\" }}>\n                        <Trash2 size={12} color={V.red}/>\n                      </button>\n                    </div>\n                  </div>\n                </div>\n              </motion.div>\n            );\n          })}\n        </div>\n      )}\n\n      <AnimatePresence>\n        {showModal && (\n          <ProductModal\n            storeId={storeId}\n            product={editing}\n            onClose={()=>{setShowModal(false);setEditing(null);}}\n            t={t}\n            isDark={isDark}\n          />\n        )}\n      </AnimatePresence>\n      <style>{`@keyframes spin{to{transform:rotate(360deg)}}`}</style>\n    </div>\n  );\n}\n","frontend/src/app/dashboard/orders/page.tsx":"\"use client\";\nimport Link from \"next/link\";\nimport { useState } from \"react\";\nimport { useQuery, useMutation, useQueryClient } from \"@tanstack/react-query\";\nimport { motion, AnimatePresence } from \"framer-motion\";\nimport { useTheme } from \"../../../components/layout/DashboardLayout\";\nimport { useAuthStore } from \"../../../store/auth.store\";\nimport { api } from \"../../../lib/api\";\nimport { useCurrency } from \"../../../lib/currency\";\nimport {\n  ShoppingCart, Search, Filter, Download, Zap,\n  Package, Truck, Check, X, Clock, RefreshCw,\n  ChevronDown, Eye, ArrowUpRight, MoreHorizontal,\n  User, MapPin, Phone, Mail, Calendar,\n} from \"lucide-react\";\nimport toast from \"react-hot-toast\";\n\nconst V = { v500: \"#6B35E8\", v400: \"#8B5CF6\", v300: \"#A78BFA\", cyan: \"#06B6D4\" };\nconst T = {\n  dark:  { card: \"#181230\", border: \"rgba(255,255,255,0.06)\", text: \"#fff\", muted: \"rgba(255,255,255,0.38)\", faint: \"rgba(255,255,255,0.04)\", row: \"rgba(255,255,255,0.02)\" },\n  light: { card: \"#fff\",    border: \"rgba(15,5,32,0.07)\",    text: \"#0D0918\", muted: \"rgba(13,9,24,0.45)\", faint: \"rgba(15,5,32,0.03)\", row: \"rgba(15,5,32,0.015)\" },\n};\n\nconst STATUS: Record<string, { label: string; color: string; bg: string; icon: any }> = {\n  PENDING:   { label: \"Pending\",   color: \"#F59E0B\", bg: \"rgba(245,158,11,0.12)\",  icon: Clock },\n  PAID:      { label: \"Paid\",      color: \"#10B981\", bg: \"rgba(16,185,129,0.12)\",  icon: Check },\n  SHIPPED:   { label: \"Shipped\",   color: \"#06B6D4\", bg: \"rgba(6,182,212,0.12)\",   icon: Truck },\n  DELIVERED: { label: \"Delivered\", color: V.v400,    bg: \"rgba(107,53,232,0.12)\",  icon: Package },\n  CANCELLED: { label: \"Cancelled\", color: \"#EF4444\", bg: \"rgba(239,68,68,0.12)\",   icon: X },\n  REFUNDED:  { label: \"Refunded\",  color: \"#8B5CF6\", bg: \"rgba(139,92,246,0.12)\",  icon: RefreshCw },\n};\n\nconst TABS = [\"All\", \"Pending\", \"Paid\", \"Shipped\", \"Delivered\", \"Cancelled\"];\n\nfunction fmt(n: number) {\n  return new Intl.NumberFormat(\"en\", { style: \"currency\", currency: \"NGN\", maximumFractionDigits: 0 }).format(n || 0);\n}\n\nfunction StatusBadge({ status }: { status: string }) {\n  const cfg = STATUS[status] || STATUS.PENDING;\n  const Icon = cfg.icon;\n  return (\n    <div className=\"inline-flex items-center gap-1.5 px-2.5 py-1 rounded-full text-xs font-semibold\"\n      style={{ background: cfg.bg, color: cfg.color }}>\n      <Icon size={10} />\n      {cfg.label}\n    </div>\n  );\n}\n\n// ── Order Detail Drawer ───────────────────────────────────────────────────────\nfunction OrderDrawer({ order, onClose, t, isDark }: { order: any; onClose: () => void; t: any; isDark: boolean }) {\n  const qc = useQueryClient();\n  const [newStatus, setNewStatus] = useState(order.status);\n  const [tracking, setTracking] = useState(order.trackingNumber || \"\");\n\n  const updateMut = useMutation({\n    mutationFn: () => api.put(`/orders/${order.storeId}/${order.id}`, { status: newStatus, trackingNumber: tracking }),\n    onSuccess: () => { toast.success(\"Order updated\"); qc.invalidateQueries({ queryKey: [\"orders\"] }); onClose(); },\n    onError: (e: any) => toast.error(e.response?.data?.message || \"Update failed\"),\n  });\n\n  return (\n    <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }}\n      className=\"fixed inset-0 z-50 flex items-center justify-end\"\n      style={{ background: \"rgba(0,0,0,0.6)\", backdropFilter: \"blur(8px)\" }}\n      onClick={e => e.target === e.currentTarget && onClose()}>\n      <motion.div initial={{ x: \"100%\" }} animate={{ x: 0 }} exit={{ x: \"100%\" }} transition={{ type: \"spring\", damping: 28 }}\n        className=\"h-full w-full max-w-md overflow-y-auto\"\n        style={{ background: isDark ? \"#181230\" : \"#fff\", borderLeft: `1px solid ${t.border}` }}>\n\n        {/* Header */}\n        <div className=\"flex items-center justify-between px-5 py-4\" style={{ borderBottom: `1px solid ${t.border}` }}>\n          <div>\n            <h2 className=\"font-bold text-sm\" style={{ color: t.text }}>Order #{order.id?.slice(-8)?.toUpperCase()}</h2>\n            <p className=\"text-xs mt-0.5\" style={{ color: t.muted }}>{new Date(order.createdAt).toLocaleDateString(\"en\", { day: \"numeric\", month: \"short\", year: \"numeric\" })}</p>\n          </div>\n          <button onClick={onClose} style={{ color: t.muted }}><X size={18} /></button>\n        </div>\n\n        <div className=\"p-5 space-y-5\">\n          {/* Status */}\n          <div className=\"rounded-2xl p-4\" style={{ background: t.faint, border: `1px solid ${t.border}` }}>\n            <p className=\"text-xs font-semibold mb-3\" style={{ color: t.muted }}>Order Status</p>\n            <div className=\"grid grid-cols-3 gap-2\">\n              {Object.entries(STATUS).map(([key, cfg]) => {\n                const Icon = cfg.icon;\n                return (\n                  <button key={key} onClick={() => setNewStatus(key)}\n                    className=\"flex flex-col items-center gap-1 p-2 rounded-xl text-center transition-all\"\n                    style={{ background: newStatus === key ? cfg.bg : \"transparent\", border: `1px solid ${newStatus === key ? cfg.color : t.border}` }}>\n                    <Icon size={13} style={{ color: newStatus === key ? cfg.color : t.muted }} />\n                    <span className=\"text-[10px] font-semibold\" style={{ color: newStatus === key ? cfg.color : t.muted }}>{cfg.label}</span>\n                  </button>\n                );\n              })}\n            </div>\n          </div>\n\n          {/* Tracking */}\n          <div>\n            <label className=\"block text-xs font-semibold mb-2\" style={{ color: t.muted }}>Tracking Number</label>\n            <input value={tracking} onChange={e => setTracking(e.target.value)} placeholder=\"e.g. GIG-12345678\"\n              className=\"w-full px-3 py-2.5 rounded-xl text-sm outline-none\"\n              style={{ background: t.faint, border: `1px solid ${t.border}`, color: t.text, fontFamily: \"inherit\" }} />\n          </div>\n\n          {/* Customer */}\n          <div className=\"rounded-2xl p-4\" style={{ background: t.faint, border: `1px solid ${t.border}` }}>\n            <p className=\"text-xs font-semibold mb-3\" style={{ color: t.muted }}>Customer</p>\n            <div className=\"space-y-2\">\n              {[\n                { icon: User,    val: order.customerName || order.customer?.name },\n                { icon: Mail,    val: order.customerEmail || order.customer?.email },\n                { icon: Phone,   val: order.customerPhone || order.customer?.phone },\n                { icon: MapPin,  val: order.shippingAddress?.address || order.deliveryAddress },\n              ].filter(i => i.val).map(({ icon: Icon, val }) => (\n                <div key={val} className=\"flex items-center gap-2\">\n                  <Icon size={12} style={{ color: t.muted, flexShrink: 0 }} />\n                  <span className=\"text-xs truncate\" style={{ color: t.text }}>{val}</span>\n                </div>\n              ))}\n            </div>\n          </div>\n\n          {/* Items */}\n          <div className=\"rounded-2xl p-4\" style={{ background: t.faint, border: `1px solid ${t.border}` }}>\n            <p className=\"text-xs font-semibold mb-3\" style={{ color: t.muted }}>Items</p>\n            <div className=\"space-y-2\">\n              {(order.items || order.orderItems || []).map((item: any, i: number) => (\n                <div key={i} className=\"flex items-center gap-3\">\n                  <div className=\"w-8 h-8 rounded-lg overflow-hidden flex-shrink-0\"\n                    style={{ background: isDark ? \"rgba(255,255,255,0.06)\" : \"#f1f5f9\" }}>\n                    {item.product?.images?.[0]\n                      ? <img src={item.product.images[0]} alt=\"\" className=\"w-full h-full object-cover\" />\n                      : <Package size={12} style={{ color: t.muted, margin: \"auto\" }} />\n                    }\n                  </div>\n                  <div className=\"flex-1 min-w-0\">\n                    <p className=\"text-xs font-semibold truncate\" style={{ color: t.text }}>{item.product?.name || item.name || \"Product\"}</p>\n                    <p className=\"text-xs\" style={{ color: t.muted }}>Qty: {item.quantity} · {fmt(item.price)}</p>\n                  </div>\n                  <p className=\"text-xs font-bold\" style={{ color: t.text }}>{fmt((item.price || 0) * (item.quantity || 1))}</p>\n                </div>\n              ))}\n            </div>\n            <div className=\"flex justify-between mt-3 pt-3\" style={{ borderTop: `1px solid ${t.border}` }}>\n              <span className=\"text-xs font-semibold\" style={{ color: t.muted }}>Total</span>\n              <span className=\"text-sm font-black\" style={{ color: \"#10B981\" }}>{fmt(order.total || order.totalAmount)}</span>\n            </div>\n          </div>\n\n          {/* Save */}\n          <button onClick={() => updateMut.mutate()} disabled={updateMut.isPending}\n            className=\"w-full py-3 rounded-xl text-sm font-bold text-white flex items-center justify-center gap-2 transition-all hover:opacity-90 disabled:opacity-60\"\n            style={{ background: `linear-gradient(135deg, ${V.v500}, #3D1C8A)` }}>\n            {updateMut.isPending ? \"Saving...\" : \"Save Changes\"}\n          </button>\n        </div>\n      </motion.div>\n    </motion.div>\n  );\n}\n\n// ── Main Page ─────────────────────────────────────────────────────────────────\nexport default function OrdersPage() {\n  const { theme } = useTheme();\n  const isDark = theme === \"dark\";\n  const t = isDark ? T.dark : T.light;\n  const storeId = useAuthStore(s => s.user?.stores?.[0]?.id);\n  const [activeTab, setActiveTab] = useState(\"All\");\n  const [search, setSearch] = useState(\"\");\n  const [selectedOrder, setSelectedOrder] = useState<any>(null);\n  const qc = useQueryClient();\n\n  const fulfillMut = useMutation({\n    mutationFn: (orderId: string) => api.patch(`/orders/${storeId}/${orderId}/status`, { status: \"SHIPPED\" }),\n    onSuccess: () => { toast.success(\"Order fulfilled!\"); qc.invalidateQueries({ queryKey: [\"orders\"] }); },\n    onError: (e: any) => toast.error(e.response?.data?.message || \"Failed to fulfill\"),\n  });\n\n  const { data, isLoading } = useQuery({\n    queryKey: [\"orders\", storeId, activeTab],\n    queryFn: () => api.get(`/orders/${storeId}${activeTab !== \"All\" ? `?status=${activeTab.toUpperCase()}` : \"\"}`).then(r => r.data.data),\n    enabled: !!storeId,\n  });\n\n  const orders: any[] = data?.orders || data || [];\n  const filtered = orders.filter(o =>\n    !search ||\n    o.id?.toLowerCase().includes(search.toLowerCase()) ||\n    (o.customerName || o.customer?.name || \"\").toLowerCase().includes(search.toLowerCase()) ||\n    (o.customerEmail || o.customer?.email || \"\").toLowerCase().includes(search.toLowerCase())\n  );\n\n  const stats = [\n    { label: \"Total Orders\",  value: orders.length,                                                    color: V.v400 },\n    { label: \"Pending\",       value: orders.filter((o: any) => o.status === \"PENDING\").length,          color: \"#F59E0B\" },\n    { label: \"Shipped\",       value: orders.filter((o: any) => o.status === \"SHIPPED\").length,          color: V.cyan },\n    { label: \"Revenue\",       value: fmt(orders.reduce((a: number, o: any) => a + (o.total || o.totalAmount || 0), 0)), color: \"#10B981\" },\n  ];\n\n  return (\n    <div style={{ maxWidth: 1400, margin: \"0 auto\" }}>\n      {/* Header */}\n      <motion.div initial={{ opacity: 0, y: -8 }} animate={{ opacity: 1, y: 0 }}\n        className=\"flex items-start justify-between gap-4 mb-6\">\n        <div>\n          <h1 style={{ fontSize: 22, fontWeight: 800, letterSpacing: \"-0.03em\", color: t.text }}>Orders</h1>\n          <p style={{ fontSize: 13, color: t.muted, marginTop: 4 }}>Track and manage customer orders</p>\n        </div>\n        <div className=\"flex gap-2\">\n          <button className=\"flex items-center gap-2 px-3 py-2 rounded-xl text-xs font-semibold\"\n            style={{ border: `1px solid ${t.border}`, color: t.muted, background: t.card }}>\n            <Download size={12} /> Export\n          </button>\n          <button className=\"flex items-center gap-2 px-3 py-2 rounded-xl text-xs font-semibold\"\n            style={{ background: \"rgba(107,53,232,0.1)\", color: V.v300, border: \"1px solid rgba(107,53,232,0.2)\" }}>\n            <Zap size={12} /> KIRO Auto-fulfil\n          </button>\n        </div>\n      </motion.div>\n\n      {/* Stats */}\n      <div className=\"grid grid-cols-2 lg:grid-cols-4 gap-3 mb-5\">\n        {stats.map((s, i) => (\n          <motion.div key={s.label} initial={{ opacity: 0, y: 12 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: i * 0.07 }}\n            className=\"rounded-2xl p-4 relative overflow-hidden\"\n            style={{ background: t.card, border: `1px solid ${t.border}` }}>\n            <div className=\"absolute top-0 left-0 right-0 h-0.5\" style={{ background: `linear-gradient(90deg, transparent, ${s.color}60, transparent)` }} />\n            <p className=\"text-2xl font-black mb-1\" style={{ color: s.color }}>{s.value}</p>\n            <p className=\"text-xs font-semibold\" style={{ color: t.text }}>{s.label}</p>\n          </motion.div>\n        ))}\n      </div>\n\n      {/* Table */}\n      <motion.div initial={{ opacity: 0, y: 8 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.2 }}\n        className=\"rounded-2xl overflow-hidden\"\n        style={{ background: t.card, border: `1px solid ${t.border}` }}>\n\n        {/* Tabs + toolbar */}\n        <div style={{ borderBottom: `1px solid ${t.border}` }}>\n          <div className=\"flex items-center px-4 gap-0 overflow-x-auto\" style={{ scrollbarWidth: \"none\" }}>\n            {TABS.map(tab => (\n              <button key={tab} onClick={() => setActiveTab(tab)}\n                className=\"py-3.5 px-3 text-xs font-semibold whitespace-nowrap transition-all flex-shrink-0\"\n                style={{ borderBottom: `2px solid ${activeTab === tab ? V.v500 : \"transparent\"}`, color: activeTab === tab ? t.text : t.muted }}>\n                {tab}\n              </button>\n            ))}\n            <div className=\"flex-1\" />\n            <div className=\"flex items-center gap-2 py-2\">\n              <div className=\"flex items-center gap-2 px-3 py-2 rounded-xl\"\n                style={{ background: t.faint, border: `1px solid ${t.border}` }}>\n                <Search size={12} style={{ color: t.muted }} />\n                <input value={search} onChange={e => setSearch(e.target.value)} placeholder=\"Search orders...\"\n                  className=\"bg-transparent border-none outline-none text-xs w-36\"\n                  style={{ color: t.text, fontFamily: \"inherit\" }} />\n              </div>\n            </div>\n          </div>\n        </div>\n\n        {/* Column headers */}\n        <div className=\"hidden md:grid px-4 py-2.5\" style={{ gridTemplateColumns: \"1fr 160px 90px 110px 110px 60px\", borderBottom: `1px solid ${t.border}` }}>\n          {[\"Customer\", \"Date\", \"Items\", \"Status\", \"Total\", \"\"].map((h, i) => (\n            <div key={i} className=\"text-[10px] font-bold uppercase tracking-wider\" style={{ color: t.muted, fontFamily: \"'Syncopate', sans-serif\" }}>{h}</div>\n          ))}\n        </div>\n\n        {/* Rows */}\n        <div className=\"divide-y\" style={{ borderColor: t.border }}>\n          {isLoading ? (\n            Array.from({ length: 5 }).map((_, i) => (\n              <div key={i} className=\"h-16 px-4 flex items-center gap-3 animate-pulse\">\n                <div className=\"h-3 rounded-full w-1/4\" style={{ background: t.faint }} />\n                <div className=\"h-3 rounded-full w-1/6\" style={{ background: t.faint }} />\n              </div>\n            ))\n          ) : filtered.length > 0 ? (\n            filtered.map((order, i) => (\n              <motion.div key={order.id} initial={{ opacity: 0 }} animate={{ opacity: 1 }} transition={{ delay: i * 0.03 }}\n                className=\"hidden md:grid items-center px-4 py-3 cursor-pointer transition-all hover:opacity-80\"\n                style={{ gridTemplateColumns: \"1fr 160px 90px 110px 110px 60px\" }}\n                onClick={() => setSelectedOrder(order)}>\n                <div>\n                  <p className=\"text-sm font-semibold\" style={{ color: t.text }}>{order.customerName || order.customer?.name || \"Customer\"}</p>\n                  <p className=\"text-xs mt-0.5\" style={{ color: t.muted }}>#{order.id?.slice(-8)?.toUpperCase()}</p>\n                </div>\n                <p className=\"text-xs\" style={{ color: t.muted }}>\n                  {new Date(order.createdAt).toLocaleDateString(\"en\", { day: \"numeric\", month: \"short\" })}\n                </p>\n                <p className=\"text-xs font-semibold\" style={{ color: t.text }}>\n                  {(order.items || order.orderItems || []).length} item{(order.items || order.orderItems || []).length !== 1 ? \"s\" : \"\"}\n                </p>\n                <StatusBadge status={order.status} />\n                <p className=\"text-sm font-bold\" style={{ color: \"#10B981\" }}>{fmt(order.total || order.totalAmount)}</p>\n                <button className=\"flex items-center justify-center w-7 h-7 rounded-lg transition-all hover:opacity-70\"\n                  style={{ background: t.faint, border: `1px solid ${t.border}` }}>\n                  <Eye size={11} style={{ color: t.muted }} />\n                </button>\n              </motion.div>\n            ))\n          ) : (\n            <div className=\"flex flex-col items-center justify-center py-20 text-center\">\n              <div className=\"w-14 h-14 rounded-2xl flex items-center justify-center mb-4\"\n                style={{ background: \"rgba(6,182,212,0.1)\", border: \"1px solid rgba(6,182,212,0.2)\" }}>\n                <ShoppingCart size={24} color={V.cyan} />\n              </div>\n              <h3 className=\"font-bold text-sm mb-2\" style={{ color: t.text }}>\n                {search ? \"No orders found\" : \"No orders yet\"}\n              </h3>\n              <p className=\"text-xs mb-5\" style={{ color: t.muted, maxWidth: 300, lineHeight: 1.6 }}>\n                {search ? \"Try a different search\" : \"Once customers start buying, all orders appear here. KIRO can help you get your first sale.\"}\n              </p>\n              {!search && (\n                <button className=\"flex items-center gap-2 px-4 py-2 rounded-xl text-xs font-bold text-white\"\n                  style={{ background: `linear-gradient(135deg, ${V.v500}, #3D1C8A)` }}>\n                  <Zap size={12} /> Ask KIRO to get first sales\n                </button>\n              )}\n            </div>\n          )}\n        </div>\n      </motion.div>\n\n      {/* Order detail drawer */}\n      <AnimatePresence>\n        {selectedOrder && <OrderDrawer order={selectedOrder} onClose={() => setSelectedOrder(null)} t={t} isDark={isDark} />}\n      </AnimatePresence>\n    </div>\n  );\n}\n"};
for(const[rel,c]of Object.entries(files)){const p=rel.split('/').join(path.sep);fs.mkdirSync(path.dirname(p),{recursive:true});fs.writeFileSync(p,c,'utf8');console.log('  ✓',rel.split('/').pop());}
try{execSync('git add .',{stdio:'inherit'});const st=execSync('git status --short',{encoding:'utf8'}).trim();if(st){execSync('git commit -m "feat: product edit + order detail pages"',{stdio:'inherit'});}execSync('git push origin main',{stdio:'inherit'});console.log('\n✅ Pushed!');process.chdir('frontend');execSync('vercel --prod --force --yes',{stdio:'inherit'});console.log('\n🚀 LIVE');}catch(e){console.log(e.message);}